<?php require __DIR__.'/includes/bootstrap.php';requireRole('admin');$statement=$pdo->prepare("SELECT e.*,u.name organiser_name FROM events e JOIN users u ON u.user_id=e.organiser_id WHERE e.status='pending' ORDER BY e.created_at ASC");$statement->execute();$pending=$statement->fetchAll();$statement=$pdo->prepare("SELECT e.*,u.name organiser_name FROM events e JOIN users u ON u.user_id=e.organiser_id WHERE e.status IN ('approved','rejected','removed') ORDER BY e.updated_at DESC LIMIT 30");$statement->execute();$all=$statement->fetchAll();$pageTitle='Admin';require __DIR__.'/includes/header.php'; ?>
<h1>Admin approval</h1><h2>Pending events</h2><?php if(!$pending):?><p class="notice">No pending events.</p><?php else:?><table><thead><tr><th>Event</th><th>Organiser</th><th class="no-print">Actions</th></tr></thead><tbody><?php foreach($pending as $event):?><tr><td><strong><?=e($event['title'])?></strong><br><?=e(date('j M Y, H:i',strtotime($event['start_time'])))?><br><?=e($event['location'])?></td><td><?=e($event['organiser_name'])?></td><td class="no-print"><div class="actions"><form method="post" action="admin_action.php"><input type="hidden" name="event_id" value="<?= (int)$event['event_id']?>"><input type="hidden" name="action" value="approve"><button>Approve</button></form><form method="post" action="admin_action.php"><input type="hidden" name="event_id" value="<?= (int)$event['event_id']?>"><input type="hidden" name="action" value="reject"><button class="danger">Reject</button></form><form method="post" action="admin_action.php"><input type="hidden" name="event_id" value="<?= (int)$event['event_id']?>"><input type="hidden" name="action" value="remove"><button class="danger">Remove</button></form></div></td></tr><?php endforeach?></tbody></table><?php endif?><h2>Recent decisions</h2><table><thead><tr><th>Event</th><th>Status</th><th class="no-print">Action</th></tr></thead><tbody><?php foreach($all as $event):?><tr><td><?=e($event['title'])?></td><td><span class="status <?=e($event['status'])?>"><?=e($event['status'])?></span></td><td class="no-print"><form method="post" action="admin_action.php"><input type="hidden" name="event_id" value="<?= (int)$event['event_id']?>"><input type="hidden" name="action" value="remove"><button class="danger">Remove</button></form></td></tr><?php endforeach?></tbody></table><?php require __DIR__.'/includes/footer.php';
